package sigma_algebra

import (
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
)

// GeneratedSigmaAlgebra — the family generated by subsets C of Ω is a
// σ-algebra on Ω containing C. The subsets of Ω form one, so the generated
// sets lie in Ω; a set is generated exactly when it lies in every σ-algebra
// on Ω containing C, and each closure law of those σ-algebras passes to
// their intersection.
var GeneratedSigmaAlgebra = generatedSigmaAlgebraThm{family.Add(registry.ProofEntry{
	Name: "GeneratedSigmaAlgebra",
	Reading: "C ⊆ {s | s ⊆ Ω} is load-bearing: otherwise no sigma algebra " +
		"on Ω contains C, and generated_sigma(Ω, C) is the universal family.",
	Key: "prop_4905e21363c55f1c",
	Build: family.Theorem(Statement{Binders: "∀Ω:set(A). ∀C:set(set(A)).",
		Hypotheses: []string{"C ⊆ {s:set(A) | s ⊆ Ω}"},
		Conclusion: "sigma_algebra_on(Ω, generated_sigma(Ω, C)) ∧ C ⊆ generated_sigma(Ω, C)"},
		func(a *Argument, Ω *Expr[Set[A]], C *Expr[Set[Set[A]]], inside Fact) {
			subsets := a.Have(
				"the subsets of Ω form a σ-algebra on Ω",
				"sigma_algebra_on(Ω, {u:set(A) | u ⊆ Ω})",
				Simp(Fwd(SigmaAlgebraOnDef)),
				BySets())
			member := a.Have(
				"a set is generated exactly when it lies in every σ-algebra on Ω containing C",
				"∀u:set(A). u ∈ generated_sigma(Ω, C) ⇔ ∀S:set(set(A)). sigma_algebra_on(Ω, S) ∧ C ⊆ S ⇒ u ∈ S",
				BySets(GeneratedSigmaDef))
			within := a.Have(
				"the generated sets lie in Ω, the subsets of Ω being one of those σ-algebras",
				"generated_sigma(Ω, C) ⊆ {u:set(A) | u ⊆ Ω}",
				By(subsets, inside, GeneratedSigmaLeast))
			carrier := a.Have(
				"Ω lies in every σ-algebra on Ω, so it is generated",
				"Ω ∈ generated_sigma(Ω, C)",
				By(member, SigmaAlgebraOnDef))
			complements := a.Have(
				"the complement in Ω of a generated set is generated",
				"∀u:set(A). u ∈ generated_sigma(Ω, C) ⇒ Ω ∖ u ∈ generated_sigma(Ω, C)",
				Derive(func(b *Argument) {
					b.FixAs[Set[A]]("u")
					generated := b.Assume()
					every := b.Have(
						"Ω ∖ u lies in every σ-algebra on Ω containing C",
						"∀S:set(set(A)). sigma_algebra_on(Ω, S) ∧ C ⊆ S ⇒ Ω ∖ u ∈ S",
						Derive(func(c *Argument) {
							c.FixAs[Set[Set[A]]]("S")
							sigma := c.Assume()
							c.Show(
								"u lies in S, which holds the complements of its sets",
								By(sigma, generated, member, SigmaAlgebraOnDef))
						}))
					b.Show(
						"so Ω ∖ u is generated",
						By(member, every))
				}))
			unions := a.Have(
				"the union of a sequence of generated sets is generated",
				"∀a:(num → set(A)). (∀n:num. a(n) ∈ generated_sigma(Ω, C)) ⇒ ⋃image(a, 𝕌) ∈ generated_sigma(Ω, C)",
				Derive(func(b *Argument) {
					b.FixAs[Fun[Nat, Set[A]]]("a")
					generated := b.Assume()
					every := b.Have(
						"the union lies in every σ-algebra on Ω containing C",
						"∀S:set(set(A)). sigma_algebra_on(Ω, S) ∧ C ⊆ S ⇒ ⋃image(a, 𝕌) ∈ S",
						Derive(func(c *Argument) {
							c.FixAs[Set[Set[A]]]("S")
							sigma := c.Assume()
							terms := c.Have(
								"every a(n) lies in S",
								"∀n:num. a(n) ∈ S",
								By(sigma, generated, member))
							c.Show(
								"S holds the union of a sequence of its sets",
								By(sigma, terms, SigmaAlgebraOnDef))
						}))
					b.Show(
						"so the union is generated",
						By(member, every))
				}))
			generators := a.Have(
				"C lies in every σ-algebra containing it, so in their intersection",
				"C ⊆ generated_sigma(Ω, C)",
				BySets(GeneratedSigmaDef))
			a.Show(
				"so the generated sets form a σ-algebra on Ω containing C",
				Simp(Fwd(SigmaAlgebraOnDef)),
				By(within, carrier, complements, unions, generators))
		}),
})}

// GeneratedSigmaLeast — the family generated by C lies in every σ-algebra
// on Ω containing C: it is the intersection of those σ-algebras, and S is
// one of them.
var GeneratedSigmaLeast = generatedSigmaLeastThm{family.Add(registry.ProofEntry{
	Name: "GeneratedSigmaLeast",
	Key:  "prop_d63e5301dfbf4d7d",
	Build: family.Theorem(Statement{Binders: "∀Ω:set(A). ∀C S:set(set(A)).",
		Hypotheses: []string{"sigma_algebra_on(Ω, S)", "C ⊆ S"},
		Conclusion: "generated_sigma(Ω, C) ⊆ S"},
		func(a *Argument, Ω *Expr[Set[A]], C, S *Expr[Set[Set[A]]], given Fact) {
			a.Show(
				"the generated family is the intersection of the σ-algebras on Ω containing C, S among them",
				BySets(given, GeneratedSigmaDef))
		}),
})}

// GeneratedSigmaInside — sets of a σ-algebra S on Ω generate a σ-algebra on Ω
// inside S. The sets of S lie in Ω, so the generated family is a σ-algebra on
// Ω, and S is one of the σ-algebras on Ω containing D, so the generated family
// lies in it.
var GeneratedSigmaInside = generatedSigmaInsideThm{family.Add(registry.ProofEntry{
	Name: "GeneratedSigmaInside",
	Key:  "prop_ce1f599ad7f86dc1",
	Build: family.Theorem(Statement{
		Binders: "∀Ω:set(A). ∀S D:set(set(A)).",
		Hypotheses: []string{
			"sigma_algebra_on(Ω, S)",
			"D ⊆ S",
		},
		Conclusion: "sigma_algebra_on(Ω, generated_sigma(Ω, D)) ∧ generated_sigma(Ω, D) ⊆ S",
	}, func(a *Argument, Ω *Expr[Set[A]], S, D *Expr[Set[Set[A]]], sigma, inS Fact) {
		a.Show(
			"the sets of D lie in Ω, and the σ-algebra they generate is the least one on Ω holding them",
			By(
				sigma,
				inS,
				SigmaAlgebraOnDef.At(Ω, S),
				set_order.SubsetTrans.At(D, S, a.TermAs[Set[Set[A]]]("{s:set(A) | s ⊆ Ω}")),
				GeneratedSigmaAlgebra.At(Ω, D),
				GeneratedSigmaLeast.At(Ω, D, S)))
	}),
})}
